import{_ as a,a0 as r,w as i,s as p,I as s,x as e,a1 as n,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"使用Linux的lsblk命令列出块设备信息 | LCTT x X-CMD","titleTemplate":false,"description":"使用Linux的lsblk命令列出块设备信息 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用Linux的lsblk命令列出块设备信息 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用Linux的lsblk命令列出块设备信息 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140617 How to use Linux lsblk Command to List Block Device Information","title":"使用Linux的lsblk命令列出块设备信息","tag":"201407","desc":""},"relativePath":"201407/20140617 How to use Linux lsblk Command to List Block Device Information.md","filePath":"[post].md"}'),b={name:"201407/20140617 How to use Linux lsblk Command to List Block Device Information.md"};function m(u,l,k,x,g,f){const t=r("Link");return i(),p("div",null,[l[14]||(l[14]=s("h1",{id:"使用linux的lsblk命令列出块设备信息",tabindex:"-1"},[e("使用Linux的lsblk命令列出块设备信息 "),s("a",{class:"header-anchor",href:"#使用linux的lsblk命令列出块设备信息","aria-label":"Permalink to “使用Linux的lsblk命令列出块设备信息”"},"​")],-1)),l[15]||(l[15]=s("p",null,[s("strong",null,"lsblk"),e("（列出块设备）命令用于列出所有可用块设备的信息，但是，它"),s("strong",null,"不会列出RAM盘的信息"),e("。块设备有硬盘，闪存盘，CD-ROM等等。")],-1)),l[16]||(l[16]=s("h3",{id:"如何安装lsblk",tabindex:"-1"},[e("如何安装lsblk "),s("a",{class:"header-anchor",href:"#如何安装lsblk","aria-label":"Permalink to “如何安装lsblk”"},"​")],-1)),s("p",null,[l[1]||(l[1]=e("lsblk命令包含在util-linux-ng包中，现在该包改名为util-linux。这个包带了几个其它工具，如dmesg。要安装lsblk，请在",-1)),n(t,{href:"ftp://ftp.kernel.org/pub/linux/utils/util-linux/"},{default:o(()=>[...l[0]||(l[0]=[e("此处",-1)])]),_:1}),l[2]||(l[2]=e("下载util-linux包。",-1))]),l[17]||(l[17]=d(`<h3 id="fedora中安装lsblk" tabindex="-1">Fedora中安装lsblk <a class="header-anchor" href="#fedora中安装lsblk" aria-label="Permalink to “Fedora中安装lsblk”">​</a></h3><p>Fedora用户可以通过以下方法来安装该包：</p><pre><code>$ sudo yum install util-linux-ng
</code></pre><p>该命令有几个选项：</p><h3 id="默认选项" tabindex="-1">默认选项 <a class="header-anchor" href="#默认选项" aria-label="Permalink to “默认选项”">​</a></h3><p>lsblk命令默认情况下将以树状列出所有块设备。打开终端，并输入以下命令：</p><pre><code>$ lsblk
</code></pre><p>输出如下：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-default.jpg" alt="lsblk default"></p><p>7个栏目名称如下：</p><p><strong>NAME</strong> : 这是块设备名。</p><p><strong>MAJ:MIN</strong> : 本栏显示主要和次要设备号。</p><p><strong>RM</strong> : 本栏显示设备是否可移动设备。注意，在本例中设备sdb和sr0的RM值等于1，这说明他们是可移动设备。</p><p><strong>SIZE</strong> : 本栏列出设备的容量大小信息。例如298.1G表明该设备大小为298.1GB，而1K表明该设备大小为1KB。</p><p><strong>RO</strong> : 该项表明设备是否为只读。在本案例中，所有设备的RO值为0，表明他们不是只读的。</p><p><strong>TYPE</strong> :本栏显示块设备是否是磁盘或磁盘上的一个分区。在本例中，sda和sdb是磁盘，而sr0是只读存储（rom）。（LCTT译注，此处sr0的RO项没有标记为1，可能存在一些错误？）</p><p><strong>MOUNTPOINT</strong> : 本栏指出设备挂载的挂载点。</p><h3 id="列出所有设备" tabindex="-1">列出所有设备 <a class="header-anchor" href="#列出所有设备" aria-label="Permalink to “列出所有设备”">​</a></h3><p>默认选项不会列出所有空设备。要查看这些空设备，请使用以下命令：</p><pre><code>$ lsblk -a
</code></pre><p>该选项将列出所有设备，包括空设备在内。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-bytes-sda.png" alt="lsblk bytes sda"></p><h3 id="列出设备权限和属主" tabindex="-1">列出设备权限和属主 <a class="header-anchor" href="#列出设备权限和属主" aria-label="Permalink to “列出设备权限和属主”">​</a></h3><p>lsblk命令也可以用于列出一个特定设备的拥有关系，同时也可以列出组和模式。可以通过以下命令来获取这些信息：</p><pre><code>$ lsblk -m
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-permissions.png" alt="lsblk  permissions"></p><h3 id="列出指定设备" tabindex="-1">列出指定设备 <a class="header-anchor" href="#列出指定设备" aria-label="Permalink to “列出指定设备”">​</a></h3><p>该命令也可以只获取指定设备的信息。这可以通过在提供给lsblk命令的选项后指定设备名来实现。例如，你可能对了解以字节显示你的磁盘驱动器大小比较感兴趣，那么你可以通过运行以下命令来实现：</p><pre><code>$ lsblk -b /dev/sda
</code></pre><p>或者，以下命令等同：</p><pre><code>$ lsblk --bytes /dev/sda
</code></pre><h3 id="以列表形式列出不带头的设备" tabindex="-1">以列表形式列出不带头的设备 <a class="header-anchor" href="#以列表形式列出不带头的设备" aria-label="Permalink to “以列表形式列出不带头的设备”">​</a></h3><p>你也可以组合几个选项来获取指定的输出。例如，你也许想要以列表格式列出设备，而不是默认的树状格式。你可能也对移除不同栏目名称的标题感兴趣。可以将两个不同的选项组合，以获得期望的输出，命令如下：</p><pre><code>$ lsblk -nl
</code></pre><p>或者，你可以使用下面的长选项，它们也能给出相同的输出。</p><pre><code>$ lsblk --noheadings --list
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-no-header-and-list.png" alt="lsblk no header and list"></p><h3 id="列出scsi设备" tabindex="-1">列出SCSI设备 <a class="header-anchor" href="#列出scsi设备" aria-label="Permalink to “列出SCSI设备”">​</a></h3><p>要获取SCSI设备的列表，你只能使用-S选项。该选项是大写字母S，不能和-s选项混淆，该选项是用来以颠倒的顺序打印依赖的。</p><pre><code>$ lsblk -S
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-SCSI-devices.png" alt=""></p><p>lsblk列出SCSI设备，而-s是逆序选项（LCTT译注：将设备和分区的组织关系逆转过来显示），其将给出如下输出。输入命令：</p><pre><code>$ lsblk -s
</code></pre><p>或者</p><pre><code>$ lsblk --inverse
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-inverse.png" alt=""></p><p>你可以使用lsblk来获取关于你的块设备的更多信息，自己把它试着显示出来吧！</p><hr>`,48)),s("p",null,[l[4]||(l[4]=e("via: ",-1)),n(t,{href:"http://linoxide.com/linux-command/linux-lsblk-command/"},{default:o(()=>[...l[3]||(l[3]=[e("http://linoxide.com/linux-command/linux-lsblk-command/",-1)])]),_:1})]),s("p",null,[l[7]||(l[7]=e("译者：",-1)),n(t,{href:"https://github.com/GOLinux"},{default:o(()=>[...l[5]||(l[5]=[e("GOLinux",-1)])]),_:1}),l[8]||(l[8]=e(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:o(()=>[...l[6]||(l[6]=[e("wxy",-1)])]),_:1})]),s("p",null,[l[11]||(l[11]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...l[9]||(l[9]=[e("LCTT",-1)])]),_:1}),l[12]||(l[12]=e(" 原创翻译，",-1)),n(t,{href:"http://linux.cn/"},{default:o(()=>[...l[10]||(l[10]=[e("Linux中国",-1)])]),_:1}),l[13]||(l[13]=e(" 荣誉推出",-1))])])}const L=a(b,[["render",m]]);export{T as __pageData,L as default};
